%% public_key:pkix_crls_validate/3 (plan 21 step LIB80D3): certificates checked against CRLs: unrevoked and revoked
%% with their reasons, delta CRLs, stale CRLs and the update_crl fun, unknown critical extensions, bad signatures,
%% missing issuer chains, a separate CRL signer and the undetermined_details option. The CA, certificates and CRLs
%% were made once with OpenSSL (valid until 2036; the stale CRL's next update passed a second after it was made).
-module(public_key_crls).
-export([main/1]).

-include_lib("public_key/include/public_key.hrl").

main(_) ->
    Data = data(),
    D = fun(Name) -> proplists:get_value(Name, Data) end,
    Ca = public_key:pkix_decode_cert(D(ca), otp),
    Leaf = public_key:pkix_decode_cert(D(leaf), otp),
    Plain = public_key:pkix_decode_cert(D(plain), otp),
    DP = hd(public_key:pkix_dist_points(Leaf)),
    Crl = fun(Der) -> {Der, public_key:der_decode('CertificateList', Der)} end,
    Direct = [{issuer_fun, {fun(_, _, _, _) -> {ok, Ca, []} end, state}}],
    Details = [{undetermined_details, true} | Direct],
    Cases = [
        {leaf_empty, Leaf, [empty], Direct},
        {plain_revoked, Plain, [revoked], Direct},
        {leaf_hold, Leaf, [revoked], Direct},
        {leaf_delta, Leaf, [revoked, delta], Direct},
        {plain_delta, Plain, [revoked, delta], Direct},
        {delta_only, Leaf, [delta], Details},
        {stale, Plain, [stale], Direct},
        {stale_details, Plain, [stale], Details},
        {critical, Leaf, [crit], Direct},
        {critical_details, Leaf, [crit], Details},
        {no_idp, Plain, [noidp], Direct},
        {two_crls, Plain, [empty, revoked], Direct}
    ],
    [
        io:format("~p ~p~n", [Name, short(public_key:pkix_crls_validate(Cert, [{DP, Crl(D(C))} || C <- CRLs], Options))])
     || {Name, Cert, CRLs, Options} <- Cases
    ],
    Update = fun(_, _) -> Crl(D(revoked)) end,
    io:format("update_crl ~p~n", [
        short(public_key:pkix_crls_validate(Plain, [{DP, Crl(D(stale))}], [{update_crl, Update} | Direct]))
    ]),
    Same = fun(_, Current) -> Current end,
    io:format("update_crl same ~p~n", [
        short(public_key:pkix_crls_validate(Plain, [{DP, Crl(D(stale))}], [{update_crl, Same} | Details]))
    ]),
    io:format("combined form ~p~n", [
        short(public_key:pkix_crls_validate(Plain, [{DP, Crl(D(revoked)), {undefined, undefined}}], Direct))
    ]),
    Tampered = tamper(D(revoked)),
    io:format("bad signature ~p ~p~n", [
        short(public_key:pkix_crls_validate(Plain, [{DP, Crl(Tampered)}], Direct)),
        short(public_key:pkix_crls_validate(Plain, [{DP, Crl(Tampered)}], Details))
    ]),
    NoChain = [{undetermined_details, true}, {issuer_fun, {fun(_, _, _, State) -> {error, State} end, state}}],
    io:format("no chain ~p~n", [short(public_key:pkix_crls_validate(Plain, [{DP, Crl(D(revoked))}], NoChain))]),
    Self = self(),
    Recording = fun(Point, _, Issuer, State) ->
        Self ! {issuer_fun, Point =:= DP, Issuer, State},
        {ok, Ca, []}
    end,
    public_key:pkix_crls_validate(Leaf, [{DP, Crl(D(empty))}], [{issuer_fun, {Recording, my_state}}]),
    io:format("issuer_fun ~p~n", [
        receive
            Message -> Message
        after 0 -> none
        end
    ]),
    Signer = [{issuer_fun, {fun(_, _, _, _) -> {ok, Ca, [D(signer)]} end, state}}],
    io:format("signer ~p ~p~n", [
        short(public_key:pkix_crls_validate(Plain, [{DP, Crl(D(signer_crl))}], Signer)),
        short(public_key:pkix_crls_validate(Leaf, [{DP, Crl(D(signer_crl))}], Signer))
    ]),
    io:format("public_key_crls: ok~n").

%% A result with each bad CRL detail reduced to its reason.
short({bad_cert, {revocation_status_undetermined, {bad_crls, Details}}}) when is_list(Details) ->
    {bad_cert, {revocation_status_undetermined, {bad_crls, [Reason || {Reason, _} <- Details]}}};
short(Result) ->
    Result.

%% A CRL whose signature's last byte is changed.
tamper(Der) ->
    Size = byte_size(Der) - 1,
    <<Body:Size/binary, Last>> = Der,
    <<Body/binary, (Last bxor 1)>>.

